function asString(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const text = asString(value);
    if (text) return text;
  }
  return '';
}

function normalizeSourceId(value) {
  return asString(value)
    .toLowerCase()
    .trim()
    .replace(/\s+/g, '_');
}

function isValidHttpUrl(value) {
  const url = asString(value);
  if (!url) return false;
  // Bewusst OHNE die URL-Klasse geprüft: im n8n-Task-Runner-Sandbox ist
  // "URL" nicht verfügbar, wodurch new URL(...) immer eine Exception warf
  // und JEDE URL fälschlich als ungültig galt.
  return /^https?:\/\/[^\s\/]+\.[^\s\/]+/i.test(url);
}

function getHostname(value) {
  const match = asString(value).match(/^https?:\/\/([^\/?#]+)/i);
  if (!match) return '';
  let host = match[1].toLowerCase();
  // evtl. userinfo@ und :port entfernen
  const atIndex = host.lastIndexOf('@');
  if (atIndex !== -1) host = host.slice(atIndex + 1);
  const colonIndex = host.indexOf(':');
  if (colonIndex !== -1) host = host.slice(0, colonIndex);
  return host.replace(/^www\./, '');
}

function domainAllowed(url, allowedDomains) {
  if (!isValidHttpUrl(url)) return false;
  if (!Array.isArray(allowedDomains) || allowedDomains.length === 0) return true;

  const host = getHostname(url);
  return allowedDomains.some((domain) => {
    const cleanDomain = asString(domain).toLowerCase().replace(/^www\./, '');
    return host === cleanDomain || host.endsWith(`.${cleanDomain}`);
  });
}

function addNote(existing, note) {
  const current = asString(existing);
  const next = asString(note);

  if (!next) return current;
  if (!current) return next;

  const parts = current
    .split('|')
    .map((part) => part.trim())
    .filter(Boolean);

  if (!parts.includes(next)) {
    parts.push(next);
  }

  return parts.join(' | ');
}

function normalizeConfidence(value) {
  if (value === null || value === undefined || value === '') return '';

  if (typeof value === 'number') {
    return String(value).replace('.', ',');
  }

  const text = String(value).trim();
  if (!text) return '';

  return text.replace('.', ',');
}

function buildFallbackSourceId(item) {
  const title = asString(item.Titel || item.title).toLowerCase();
  const venue = asString(item.Veranstaltungsort || item.venue || item.location_name).toLowerCase();
  const organizer = asString(item.Veranstalter || item.organizer).toLowerCase();
  const source = asString(item.Quelle || item.source_name).toLowerCase();
  const address = asString(item.Adresse || item.address).toLowerCase();

  const haystack = [title, venue, organizer, source, address].join(' ');

  if (haystack.includes('awo') || haystack.includes('königsberger straße 8') || haystack.includes('coerde mittendrin')) {
    return 'awo_coerde_mittendrin';
  }

  if (haystack.includes('meerwiese') && (haystack.includes('theater') || haystack.includes('stück') || haystack.includes('vorstellung'))) {
    return 'meerwiese_theater';
  }

  if (haystack.includes('meerwiese')) {
    return 'meerwiese_begegnungszentrum';
  }

  if (haystack.includes('stadtbücherei') || haystack.includes('stadtbuecherei')) {
    return 'stadtbuecherei_coerde';
  }

  if (haystack.includes('eckels') || haystack.includes('kladde') || haystack.includes('coermühle') || haystack.includes('coermuehle')) {
    return 'eckels_kladde_alle_kurse_events';
  }

  if (haystack.includes('mot-treff') || haystack.includes('kotten') || haystack.includes('coerder liekweg')) {
    return 'mot_treff_kotten';
  }

  if (haystack.includes('rock am berg')) {
    return 'rock_am_berg';
  }

  if (haystack.includes('iriba')) {
    return 'iriba_brunnen_termine';
  }

  if (haystack.includes('andreas-kirchengemeinde') || haystack.includes('andreaskirche') || haystack.includes('elfi-gottesdienst')) {
    return 'andreas_kirchengemeinde_start';
  }

  if (haystack.includes('franziskus') || haystack.includes('franziskushaus') || haystack.includes('schneidemühler')) {
    return 'st_franziskus_wocheninfo';
  }

  if (haystack.includes('fabi') || haystack.includes('familienbildungsstätte') || haystack.includes('familienbildungsstaette')) {
    return 'ev_fabi_coerde';
  }

  if (haystack.includes('kulturinitiative') || haystack.includes('coerdinale') || haystack.includes('vorlese-café') || haystack.includes('vorlese-cafe')) {
    return 'kulturinitiative_coerde';
  }

  // NEU: DRK Migrationsberatung auch über Freitext erkennen.
  if (haystack.includes('drk') || haystack.includes('migrationsberatung') || haystack.includes('hamannplatz') || haystack.includes('rotes kreuz')) {
    return 'drk_munster_migrationsberatung_mbe';
  }

  return 'unknown_source';
}

function resolveUrlAndSource(item) {
  let sourceId = normalizeSourceId(firstNonEmpty(item.source_id, item.sourceId));

  if (!sourceId || sourceId === 'unknown_source') {
    sourceId = buildFallbackSourceId(item);
  }

  const sourceDefault = SOURCE_DEFAULTS[sourceId] || null;

  let url = firstNonEmpty(
    item.URL,
    item.url,
    item.source_url,
    item.sourceUrl
  );

  // Umlaut-Variante zuerst (im Sheet die gefüllte), dann ue-Alias und sonstige
  let note = firstNonEmpty(
    item['Hinweise_Prüfstatus'],
    item['Hinweise_Pruefstatus'],
    item.Hinweise_Pruefstatus,
    item.review_notes,
    item.notes
  );

  // GEÄNDERT (Option 2): Robuste URL-Behandlung.
  // Schritt 1: Liegt bereits eine gültige http(s)-URL vor, wird sie als
  // vertrauenswürdige Event-URL behandelt und IMMER behalten — unabhängig
  // davon, ob die Quelle bekannt ist. Es findet KEINE Domain-Verwerfung mehr
  // statt, die eine gültige Event-URL nur wegen unbekannter/abweichender
  // Quelle löschen würde.
  const hasValidEventUrl = isValidHttpUrl(url);

  if (!hasValidEventUrl) {
    // Keine gültige URL vorhanden -> Quellen-Hauptseite als Fallback setzen.
    url = sourceDefault ? sourceDefault.url : '';
    if (url) {
      note = addNote(note, 'URL auf Quellen-Hauptseite gesetzt');
    } else {
      note = addNote(note, 'MANUELL PRÜFEN: URL fehlt');
    }
  } else if (sourceDefault && !domainAllowed(url, sourceDefault.allowed_domains)) {
    // Nur bei BEKANNTER Quelle UND tatsächlich abweichender Domain wird die
    // URL als Fremdquelle korrigiert. Bei unbekannter Quelle (sourceDefault
    // == null) bleibt die gültige Event-URL erhalten.
    url = sourceDefault.url;
    note = addNote(note, 'URL wegen abweichender Fremdquelle auf Quellen-Hauptseite korrigiert');
  }

  let sourceName = firstNonEmpty(item.Quelle, item.source_name, item.sourceName);

  if (!sourceName && sourceDefault) {
    sourceName = sourceDefault.source_name;
  }

  if (!sourceName) {
    sourceName = 'Quelle unbekannt';
    note = addNote(note, 'MANUELL PRÜFEN: Quelle unbekannt');
  }

  return {
    sourceId,
    sourceName,
    url,
    note,
  };
}

// NEU: Zeit-Fallback anwenden. Setzt time_start/time_end (und Uhrzeit,
// falls leer) NUR, wenn bislang keine Startzeit vorhanden ist.
function applyTimeFallbacks(output) {
  const currentTimeStart = asString(output.time_start);
  if (currentTimeStart) return output; // extrahierte Uhrzeit hat immer Vorrang

  const titleLower = asString(output.Titel).toLowerCase();
  const sourceIdLower = asString(output.source_id).toLowerCase();

  for (const fb of TIME_FALLBACKS) {
    const sourceMatch = !fb.source_id || sourceIdLower === asString(fb.source_id).toLowerCase();
    const titleMatch = !fb.title_includes || titleLower.includes(asString(fb.title_includes).toLowerCase());

    if (sourceMatch && titleMatch) {
      output.time_start = asString(fb.time_start);
      output.time_end = asString(fb.time_end);

      if (!asString(output.Uhrzeit)) {
        output.Uhrzeit = output.time_end
          ? `${output.time_start} – ${output.time_end}`
          : output.time_start;
      }

      output['Hinweise_Prüfstatus'] = addNote(
        output['Hinweise_Prüfstatus'],
        'Uhrzeit per Fallback gesetzt (Extraktion lieferte keine Zeit)'
      );

      break; // erster Treffer gewinnt
    }
  }

  return output;
}

function buildOutputItem(item) {
  const resolved = resolveUrlAndSource(item);

  const output = {
    event_id: firstNonEmpty(item.event_id, item.eventId),
    sort_key: firstNonEmpty(item.sort_key, item.sortKey),

    Datum: firstNonEmpty(item.Datum, item.date_de, item.date),
    Uhrzeit: firstNonEmpty(item.Uhrzeit, item.time_range, item.zeitraum),

    Titel: firstNonEmpty(item.Titel, item.title, item.titel),
    Veranstaltungsort: firstNonEmpty(item.Veranstaltungsort, item.venue, item.location_name, item.ort),
    Adresse: firstNonEmpty(item.Adresse, item.street, item.address, item.strasse),
    Ort: firstNonEmpty(item.Ort, item.district, item.city, item.stadtteil),

    Veranstalter: firstNonEmpty(item.Veranstalter, item.organizer, item.veranstalter),
    Kategorie: firstNonEmpty(item.Kategorie, item.category, item.kategorie),
    Kurzbeschreibung: firstNonEmpty(item.Kurzbeschreibung, item.description, item.short_description, item.beschreibung),

    Quelle: resolved.sourceName,
    URL: resolved.url,

    confidence: normalizeConfidence(item.confidence),
    'Hinweise_Prüfstatus': resolved.note,
    publish: firstNonEmpty(item.publish),

    // Finale Spalten ohne _iso; Eingabe-Aliase werden weiterhin gelesen
    date_start: firstNonEmpty(item.date_start, item.date_start_iso, item.start_date),
    date_end: firstNonEmpty(item.date_end, item.date_end_iso, item.end_date),
    time_start: firstNonEmpty(item.time_start, item.start_time),
    time_end: firstNonEmpty(item.time_end, item.end_time),

    source_id: resolved.sourceId,
  };

  // NEU: Zeit-Fallbacks (greifen nur bei leerem time_start)
  applyTimeFallbacks(output);

  if (!output.URL) {
    output['Hinweise_Prüfstatus'] = addNote(output['Hinweise_Prüfstatus'], 'MANUELL PRÜFEN: URL fehlt');
  }

  if (!output.Titel) {
    output['Hinweise_Prüfstatus'] = addNote(output['Hinweise_Prüfstatus'], 'MANUELL PRÜFEN: Titel fehlt');
  }

  if (!output.Datum) {
    output['Hinweise_Prüfstatus'] = addNote(output['Hinweise_Prüfstatus'], 'MANUELL PRÜFEN: Datum fehlt');
  }

  // Nur die finalen Spalten ausgeben — eliminiert Alias-/Doppelspalten
  // (z. B. Hinweise_Pruefstatus ohne Umlaut, date_start_iso etc.)
  const finalOutput = {};
  for (const column of FINAL_COLUMNS) {
    finalOutput[column] = output[column] ?? '';
  }

  return finalOutput;
}

const builtItems = inputItems.map((item) => buildOutputItem(item.json || {}));

let finalItems = builtItems;

if (ENABLE_EVENT_ID_DEDUP) {
  const seen = new Set();
  finalItems = builtItems.filter((row) => {
    const id = asString(row.event_id);
    if (!id) return true; // ohne event_id defensiv durchlassen
    if (seen.has(id)) return false;
    seen.add(id);
    return true;
  });
}

return finalItems.map((json) => ({ json }));

// ============================================================
// n8n Function-Node: "Build GitHub OpenData Payloads"
// ANGEPASST an die deutschen Feldnamen aus "Letzte Korrekturen".
// Erzeugt JSON / CSV / ICS / GeoJSON als Base64-Payloads für die
// GitHub Contents API.
//
// INPUT-Felder pro Event (deutsch + technisch):
//   event_id, Titel, Datum, Uhrzeit, Veranstaltungsort, Adresse,
//   Ort, Veranstalter, Kategorie, Kurzbeschreibung, Quelle, URL,
//   confidence, publish, date_start, date_end, time_start, time_end,
//   source_id
//
// publish === "nein"  -> Event wird NICHT veröffentlicht (Absage etc.)
// ============================================================

const REPO_BRANCH = 'main';

// ----- Events einsammeln -----
const inputItems = $input.all();
let events = [];
if (inputItems.length === 1 && Array.isArray(inputItems[0].json.events)) {
  events = inputItems[0].json.events;
} else {
  events = inputItems.map(i => i.json);
}

// ----- Filter: nur valide, veröffentlichbare Events -----
events = events.filter(e => {
  if (!e) return false;
  // technische Pflichtfelder (deutsche Titel-Spalte + technisches Startdatum)
  const hasTitle = e.Titel || e.title;
  const hasDate = e.date_start || e.start_date;
  if (!hasTitle || !hasDate) return false;
  // Absagen / nicht-publizieren ausschließen
  const pub = String(e.publish || '').trim().toLowerCase();
  if (pub === 'nein' || pub === 'no' || pub === 'false') return false;
  return true;
});

// ----- stabil sortieren nach date_start + time_start -----
events.sort((a, b) => {
  const da = String(a.date_start || a.start_date || '') + 'T' + String(a.time_start || a.start_time || '00:00');
  const db = String(b.date_start || b.start_date || '') + 'T' + String(b.time_start || b.start_time || '00:00');
  if (da !== db) return da < db ? -1 : 1;
  return String(a.Titel || a.title || '').localeCompare(String(b.Titel || b.title || ''), 'de');
});

const generatedAt = new Date().toISOString();
const commitMessage = `chore(data): update events (${events.length} Termine, ${generatedAt.slice(0, 10)})`;

// ----- Hilfsfunktionen -----
function b64(str) { return Buffer.from(str, 'utf8').toString('base64'); }
function val(e, ...keys) {
  for (const k of keys) {
    if (e[k] !== undefined && e[k] !== null && e[k] !== '') return e[k];
  }
  return '';
}
function nullable(e, ...keys) {
  const v = val(e, ...keys);
  return v === '' ? null : v;
}
function csvCell(v) {
  const s = v === null || v === undefined ? '' : String(v);
  return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
function icsEsc(v) {
  return String(v == null ? '' : v)
    .replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n');
}
function icsDateTime(dateStr, timeStr) {
  const d = String(dateStr).replace(/-/g, '');
  if (timeStr && /^\d{2}:\d{2}$/.test(timeStr)) return d + 'T' + timeStr.replace(':', '') + '00';
  return d;
}
function icsFold(line) {
  if (line.length <= 75) return line;
  let out = line.slice(0, 75), rest = line.slice(75);
  while (rest.length > 74) { out += '\r\n ' + rest.slice(0, 74); rest = rest.slice(74); }
  return out + '\r\n ' + rest;
}
function toNum(v) { const n = Number(v); return Number.isFinite(n) ? n : null; }

// einheitliches, normalisiertes Event-Objekt (für JSON-Ausgabe)
function normEvent(e) {
  return {
    event_id: val(e, 'event_id'),
    title: val(e, 'Titel', 'title'),
    start_date: val(e, 'date_start', 'start_date'),
    start_time: nullable(e, 'time_start', 'start_time'),
    end_date: nullable(e, 'date_end', 'end_date'),
    end_time: nullable(e, 'time_end', 'end_time'),
    location_name: val(e, 'Veranstaltungsort', 'location_name'),
    address: val(e, 'Adresse', 'address'),
    city: val(e, 'Ort', 'city') || 'Münster-Coerde',
    organizer: val(e, 'Veranstalter', 'organizer'),
    category: val(e, 'Kategorie', 'category'),
    short_description: val(e, 'Kurzbeschreibung', 'short_description'),
    status: 'scheduled',
    source_name: val(e, 'Quelle', 'source_name'),
    source_url: val(e, 'URL', 'source_url'),
    source_id: val(e, 'source_id'),
    confidence: val(e, 'confidence'),
    last_updated: generatedAt,
  };
}

const norm = events.map(normEvent);

// ============================================================
// events.json
// ============================================================
const jsonObj = {
  dataset: 'coerde-events',
  description: 'Öffentliche Veranstaltungen in Münster-Coerde',
  license: 'CC-BY-4.0',
  generated_at: generatedAt,
  event_count: norm.length,
  events: norm,
};
const jsonStr = JSON.stringify(jsonObj, null, 2) + '\n';

// ============================================================
// events.csv
// ============================================================
const csvHeader = ['event_id','title','start_date','start_time','end_date','end_time',
  'location_name','address','city','organizer','category','status','source_name','source_url','last_updated'];
const csvLines = [csvHeader.join(',')];
for (const e of norm) {
  csvLines.push([
    csvCell(e.event_id), csvCell(e.title), csvCell(e.start_date), csvCell(e.start_time || ''),
    csvCell(e.end_date || ''), csvCell(e.end_time || ''), csvCell(e.location_name), csvCell(e.address),
    csvCell(e.city), csvCell(e.organizer), csvCell(e.category), csvCell(e.status),
    csvCell(e.source_name), csvCell(e.source_url), csvCell(e.last_updated),
  ].join(','));
}
const csvStr = csvLines.join('\r\n') + '\r\n';

// ============================================================
// events.ics
// ============================================================
const dtstamp = generatedAt.replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'Z');
const icsLines = [
  'BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Coerde Events//Open Data//DE',
  'CALSCALE:GREGORIAN','METHOD:PUBLISH','X-WR-CALNAME:Coerde Events',
  'X-WR-CALDESC:Öffentliche Veranstaltungen in Münster-Coerde','X-WR-TIMEZONE:Europe/Berlin',
];
for (const e of norm) {
  const allDay = !(e.start_time && /^\d{2}:\d{2}$/.test(e.start_time));
  const dtstart = icsDateTime(e.start_date, e.start_time);
  let dtend = null;
  if (e.end_date || e.end_time) dtend = icsDateTime(e.end_date || e.start_date, e.end_time || e.start_time);
  const locParts = [e.location_name, e.address, e.city].filter(Boolean).join(', ');
  const descParts = [e.short_description, e.organizer ? 'Veranstalter: ' + e.organizer : '',
    e.source_url ? 'Quelle: ' + e.source_url : ''].filter(Boolean).join('\n');

  icsLines.push('BEGIN:VEVENT');
  icsLines.push(icsFold('UID:' + icsEsc(e.event_id) + '@coerde-events'));
  icsLines.push('DTSTAMP:' + dtstamp);
  if (allDay) {
    icsLines.push('DTSTART;VALUE=DATE:' + dtstart);
    if (dtend) icsLines.push('DTEND;VALUE=DATE:' + dtend);
  } else {
    icsLines.push('DTSTART;TZID=Europe/Berlin:' + dtstart);
    if (dtend) icsLines.push('DTEND;TZID=Europe/Berlin:' + dtend);
  }
  icsLines.push(icsFold('SUMMARY:' + icsEsc(e.title)));
  if (locParts) icsLines.push(icsFold('LOCATION:' + icsEsc(locParts)));
  if (descParts) icsLines.push(icsFold('DESCRIPTION:' + icsEsc(descParts)));
  if (e.source_url) icsLines.push(icsFold('URL:' + icsEsc(e.source_url)));
  if (e.category) icsLines.push(icsFold('CATEGORIES:' + icsEsc(e.category)));
  icsLines.push('STATUS:CONFIRMED');
  icsLines.push('END:VEVENT');
}
icsLines.push('END:VCALENDAR');
const icsStr = icsLines.join('\r\n') + '\r\n';

// ============================================================
// events.geojson (nur Events mit Koordinaten – aktuell keine)
// ============================================================
const features = [];
for (const e of events) {
  const lat = toNum(e.latitude ?? e.lat);
  const lng = toNum(e.longitude ?? e.lng ?? e.lon);
  if (lat === null || lng === null) continue;
  features.push({
    type: 'Feature',
    geometry: { type: 'Point', coordinates: [lng, lat] },
    properties: {
      event_id: val(e, 'event_id'), title: val(e, 'Titel', 'title'),
      start_date: val(e, 'date_start', 'start_date'),
      organizer: val(e, 'Veranstalter', 'organizer'),
      source_url: val(e, 'URL', 'source_url'),
    },
  });
}
const geojsonStr = JSON.stringify({ type: 'FeatureCollection', features }, null, 2) + '\n';

// ============================================================
// Vier Output-Items
// ============================================================
const files = [
  { repo_path: 'data/events.json',    content: jsonStr },
  { repo_path: 'data/events.csv',     content: csvStr },
  { repo_path: 'data/events.ics',     content: icsStr },
  { repo_path: 'data/events.geojson', content: geojsonStr },
];

return files.map(f => ({
  json: {
    repo_path: f.repo_path,
    branch: REPO_BRANCH,
    commit_message: commitMessage,
    content_b64: b64(f.content),
    event_count: norm.length,
    generated_at: generatedAt,
  },
}));

// Führt Build-Payloads und Get-SHA-Ergebnisse über repo_path zusammen
// (robuster als Index-Matching).

const getItems = $input.all();
const buildItems = $('OpenData Serienfelder ergänzen').all();

// sha pro Pfad aus den Get-SHA-Ergebnissen sammeln
const shaByPath = {};
for (const it of getItems) {
  const j = it.json || {};
  // Pfad aus der GitHub-Antwort (j.path) ODER aus dem mitgereichten repo_path
  const path = j.path || j.repo_path;
  if (path && !j.error && j.sha) {
    shaByPath[path] = j.sha;
  }
}

// Build-Payloads mit passendem sha anreichern
return buildItems.map((b) => {
  const build = b.json;
  const sha = shaByPath[build.repo_path] || null;
  return {
    json: {
      repo_path: build.repo_path,
      branch: build.branch,
      commit_message: build.commit_message,
      content_b64: build.content_b64,
      existing_sha: sha,   // null = neu anlegen
      retry_count: 0,      // NEU: Zaehler fuer den 409-Retry-Mechanismus
    },
  };
});

const TZ = 'Europe/Berlin';

const SOURCE_NAME = 'Stadt Münster Veranstaltungskalender';
const SOURCE_ENDPOINT = 'https://events-calendar.stadt-muenster.de/graphql';
const DETAIL_URL_BASE = 'https://www.stadt-muenster.de/veranstaltungskalender/-/detail';

// Titel -> URL-Slug (das Frontend routet ueber die beiden IDs;
// der Slug dient der Lesbarkeit und wird aus dem Titel abgeleitet)
function slugifyTitle(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .replace(/ß/g, 'ss')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

function buildDetailUrl(eventInfoId, eventDateId, title) {
  if (!eventInfoId || !eventDateId) return '';
  return `${DETAIL_URL_BASE}/${eventInfoId}/${eventDateId}/${slugifyTitle(title)}`;
}


// Begriffe, anhand derer wir Münster-Nord herausfiltern.
const NORTH_TERMS = [
  'coerde',
  'meerwiese',
  'begegnungszentrum meerwiese',
  'theater in der meerwiese',
  'speicher 3',
  'speicher3',
  'speicher 10',
  'stadtteilbücherei coerde',
  'stadtteilbuecherei coerde',
  'bücherei coerde',
  'buecherei coerde',
  'kulturinitiative coerde'
];

function cleanText(value) {
  if (value === null || value === undefined) return '';

  return String(value)
    .replace(/\[\.\.\.\]/g, '')
    .replace(/\r/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}

function stripHtml(value) {
  return cleanText(value)
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'");
}

function berlinDateTimeParts(isoString) {
  if (!isoString) {
    return { date: '', time: '' };
  }

  const date = new Date(isoString);

  if (Number.isNaN(date.getTime())) {
    return { date: '', time: '' };
  }

  const parts = new Intl.DateTimeFormat('de-DE', {
    timeZone: TZ,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23'
  }).formatToParts(date);

  const map = {};
  for (const part of parts) {
    map[part.type] = part.value;
  }

  return {
    date: `${map.year}-${map.month}-${map.day}`,
    time: `${map.hour}:${map.minute}`
  };
}

function isNorthEvent(event) {
  const info = event.eventInfo || {};
  const schedule = event.eventSchedule || {};
  const location = schedule.eventLocation || {};

  const haystack = [
    info.title,
    info.subtitle,
    info.description,
    location.name
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();

  return NORTH_TERMS.some(term => haystack.includes(term));
}

function buildTitle(title, subtitle) {
  const cleanTitle = cleanText(title);
  const cleanSubtitle = cleanText(subtitle);

  if (!cleanTitle && !cleanSubtitle) return '';
  if (!cleanSubtitle) return cleanTitle;
  if (cleanTitle.toLowerCase().includes(cleanSubtitle.toLowerCase())) return cleanTitle;

  return `${cleanTitle} – ${cleanSubtitle}`;
}

const input = items[0]?.json || {};

const eventDates =
  input?.data?.eventDates?.data ||
  input?.eventDates?.data ||
  [];

const paginatorInfo =
  input?.data?.eventDates?.paginatorInfo ||
  input?.eventDates?.paginatorInfo ||
  null;

const preparedEvents = [];

for (const event of eventDates) {
  if (!event) continue;

  if (!isNorthEvent(event)) {
    continue;
  }

  const info = event.eventInfo || {};
  const schedule = event.eventSchedule || {};
  const location = schedule.eventLocation || {};
  const recurrence = schedule.recurrence || null;

  const start = berlinDateTimeParts(event.start);
  const end = berlinDateTimeParts(event.end);

  const fullDay = schedule.full_day === true;

  const title = buildTitle(info.title, info.subtitle);
  const description = stripHtml(info.description);

  if (!title || !start.date) {
    continue;
  }

  const venueName = cleanText(location.name);

  preparedEvents.push({
    event_id: `stadt_muenster_${event.id}`,
    title,
    subtitle: cleanText(info.subtitle),
    start_date: start.date,
    start_time: fullDay ? '' : start.time,
    end_date: end.date || '',
    end_time: fullDay ? '' : end.time,
    full_day: fullDay,
    location: venueName,
    // NEU: 'venue' zusätzlich zu 'location'. detectSourceDefault() prüft obj.venue,
    // nicht obj.location. Nur so können bekannte Coerde-Orte (Bücherei, Eckels,
    // Meerwiese ...) erkannt werden und ihre echte URL/Kategorie aus
    // SOURCE_DEFAULTS erben.
    venue: venueName,
    description,
    source: SOURCE_NAME,
    // NEU: buildRow liest die Quelle aus 'source_name', nicht aus 'source'.
    // Ohne dieses Feld bleibt die Quelle bei API-Events leer.
    source_name: SOURCE_NAME,
    source_type: 'graphql',
    // GEÄNDERT: KEIN Endpoint mehr als URL. buildRow las source_url als URL-Fallback
    // und zeigte dadurch den GraphQL-Endpoint als "Event-URL" an.
    // Echte Detail-URL des staedtischen Veranstaltungskalenders
    // (Muster: /detail/<eventInfoId>/<eventDateId>/<slug>).
    source_url: buildDetailUrl(info.id, event.id, title),
    url: buildDetailUrl(info.id, event.id, title),
    // Endpoint nur zur Herkunfts-Doku. buildRow liest dieses Feld NICHT als Link.
    provenance_endpoint: SOURCE_ENDPOINT,
    city_area: 'Münster-Nord',
    original_event_id: event.id,
    original_event_info_id: info.id || '',
    recurrence
  });
}

const openAiLikePayload = {
  data: preparedEvents
};

return [
  {
    json: {
      source: SOURCE_NAME,
      provenance_endpoint: SOURCE_ENDPOINT,   // nur Metadaten des Batches, nicht pro Event
      total_received_from_api: eventDates.length,
      total_after_north_filter: preparedEvents.length,
      paginatorInfo,
      openai_response: JSON.stringify(openAiLikePayload),
      choices: [
        {
          message: {
            content: JSON.stringify(openAiLikePayload)
          }
        }
      ]
    }
  }
];

// ============================================================
// Coerde FamilienBildung Kurssuche abrufen + vorbereiten
// n8n Code Node — Mode: Run Once for All Items
//
// STAND September 2026 — WICHTIGE AENDERUNG:
// Die Website hat den Suchfilter "Aussenstelle = Coerde" entfernt.
// Der frueher genutzte POST auf /kurssuche/suche liefert deshalb
// nicht mehr die Coerde-Kurse, sondern die komplette Kursliste
// (Friedensstr., UKM, Hiltrup, Amelsbueren ...). Symptom war ein
// Einbruch von ~255 auf ~36 Termine.
//
// NEUES VERFAHREN:
//   1. Alle Seiten der Kursliste per GET durchblaettern
//      (/kurssuche/liste bzw. ?knr=<letzte Kursnr>&browse=forward).
//      Kein Cookie, kein POST, kein Suchformular noetig.
//   2. Aus der Liste je Kurs die Kursnummer, den Slug UND den
//      angezeigten Kursort auslesen.
//   3. Offensichtlich fremde Orte (Hauptgebaeude, Hiltrup, UKM ...)
//      direkt verwerfen -> spart pro Kurs zwei HTTP-Requests.
//   4. Nur fuer die verbleibenden Kurse ICS-Export (exakte Termine)
//      + Detailseite (Status/Beschreibung) holen und danach mit der
//      vollstaendigen Adresse endgueltig klassifizieren.
//
// Laeuft am LLM vorbei (skip_openai: true), analog zur AWO- und
// TEC-Weiche in "OpenAI Anfrage vorbereiten".
// ============================================================

const BASE = 'https://www.familienbildung-friedensstrasse.de';
const SOURCE_NAME = 'FamilienBildung Friedensstraße';
const DEFAULT_ORGANIZER = 'FamilienBildung Friedensstraße';
const DEFAULT_CATEGORY = 'Bildung / Familie / Stadtteil';
const DEFAULT_CITY = 'Münster-Coerde';
const MAX_PAGES = 30;          // Sicherheitsgrenze Listen-Paginierung
const MAX_COURSE_FETCHES = 150; // Sicherheitsgrenze ICS-/Detail-Abrufe
const USER_AGENT = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36';

function decodeHtmlEntities(value) {
  return String(value || '')
    .replace(/&#(\d+);/g, (m, dec) => String.fromCharCode(Number(dec)))
    .replace(/&#x([0-9a-fA-F]+);/g, (m, hex) => String.fromCharCode(parseInt(hex, 16)))
    .replace(/&amp;/g, '&')
    .replace(/&ouml;/g, 'ö')
    .replace(/&auml;/g, 'ä')
    .replace(/&uuml;/g, 'ü')
    .replace(/&Ouml;/g, 'Ö')
    .replace(/&Auml;/g, 'Ä')
    .replace(/&Uuml;/g, 'Ü')
    .replace(/&szlig;/gi, 'ß')
    .replace(/&eacute;/g, 'é')
    .replace(/&Eacute;/g, 'É')
    .replace(/&egrave;/g, 'è')
    .replace(/&agrave;/g, 'à')
    .replace(/&ccedil;/g, 'ç')
    .replace(/&euro;/gi, '€')
    .replace(/&reg;/gi, '®')
    .replace(/&copy;/gi, '©')
    .replace(/&trade;/gi, '™')
    .replace(/&ndash;/g, '–')
    .replace(/&mdash;/g, '—')
    .replace(/&nbsp;/g, ' ')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

// ============================================================
// Ortsfilter
// Die Kursliste umfasst inzwischen ALLE Standorte des Traegers.
// Nur eindeutig Coerder Orte kommen in den Kalender; unklare Orte
// werden im Output zur Pruefung gemeldet (siehe unklare_orte).
// ============================================================

const COERDE_LOCATION_TERMS = [
  'coerde',              // "Münster-Coerde", "coerde mittendrin", "Stadtteilbüro Coerde"
  'kiesekampweg',        // Kita Wertvoll
