  'meerwiese',           // Begegnungszentrum / DRK Kita / An der Meerwiese
  'nerzweg',             // Stadtteilbüro Coerde der AWO
  'königsberger str',    // coerde mittendrin
  'koenigsberger str',
  'hamannplatz',
  'breslauer str',
  '48157',               // PLZ Coerde (Ausnahmen stehen in der Blacklist unten,
                         // die Blacklist hat Vorrang)
];

const NON_COERDE_LOCATION_TERMS = [
  // --- Hauptgebaeude Friedensstr. 5 (Innenstadt) ---
  'fbf/',                // Listenschreibweise: "FBF/Gymnastikraum, 3. Etage"
  'friedensstr',
  // --- Kinderhaus ---
  'papst-johannes-schule',
