// Standard false, weil eine kleine Nebenquelle nicht den kompletten
// Lauf inkl. GitHub-Veroeffentlichung blockieren soll.
const ABORT_ON_ERROR = false;

// ============================================================
// Ortsfilter (Blacklist hat Vorrang)
// Geprueft wird nur: Veranstaltungsort + Adresse + PLZ + Stadt.
// ============================================================

const COERDE_LOCATION_TERMS = [
