        'Manuell gepflegt (Quelle: Flyer Workshop-Reihe 2026 Coerde/Franziskushaus, in Kooperation mit Smart City Münster und Münster Marketing)'
    },

    // Inhalte – KEINE Wörter wie "jeden", "montags", "wöchentlich" verwenden!
    events: [
      {
        date: '2026-11-09',
        title: 'Das Smartphone sicher einstellen und für den Notfall vorsorgen',
        short_description:
          `Workshop 1/4 der Reihe ${DIGI_SERIES_NAME}: Smartphone sicher einstellen und für Verlust, Diebstahl oder Beschädigung vorsorgen. ${DIGI_FOOTER}`
      },
      {
        date: '2026-11-16',
        title: 'Sichere Passwörter und Schutz vor Betrugsmaschen',
        short_description:
          `Workshop 2/4 der Reihe ${DIGI_SERIES_NAME}: sichere Passwörter, Betrugsmaschen und verdächtige Nachrichten erkennen. ${DIGI_FOOTER}`
      },
      {
        date: '2026-11-23',
        title: 'Sicher online bezahlen',
        short_description:
          `Workshop 3/4 der Reihe ${DIGI_SERIES_NAME}: sicher online einkaufen und bezahlen, seriöse Shops und Sicherheitsmerkmale erkennen. ${DIGI_FOOTER}`
      },
      {
        date: '2026-11-30',
        title: 'Nachrichten und Mediatheken sicher nutzen',
        short_description:
          `Workshop 4/4 der Reihe ${DIGI_SERIES_NAME}: Nachrichten-Apps, Mediatheken und vertrauenswürdige Quellen am Smartphone. ${DIGI_FOOTER}`
      }
    ]
  }
];

// ============================================================
// Hauptlogik
// ============================================================

if (!inputItems.length) {
  return [];
}

const todayIso = getTodayIsoInTimeZone(TIMEZONE);
const horizonEndIso = addDaysIso(todayIso, HORIZON_DAYS);

const manualItems = [];

// --- A) Serien ---
for (const series of MANUAL_SERIES) {
  if (!series || series.enabled !== true) continue;

  validateSeries(series);

  if (series.auto_replace && sourceAlreadyListsSeries(inputItems, series.auto_replace)) {
    console.log(`[Manuelle Termine] Serie "${series.key}" übersprungen – reguläre Quelle liefert den Termin bereits.`);
    continue;
  }

  const dates = buildOccurrenceDates(series, todayIso, horizonEndIso);
  if (!dates.length) continue;

  const events = dates.map((dateIso) => buildSeriesEvent(series, dateIso));

  manualItems.push({
    json: {
      source: { ...series.source },
      data: events,
      manual_source: true,
      manual_series_key: series.key
    },
    pairedItem: { item: 0 }
  });
}

// --- B) Einzeltermine ---
for (const group of MANUAL_SINGLE_EVENTS) {
  if (!group || group.enabled !== true) continue;

  validateSingleGroup(group);

  const events = [];

  for (const entry of group.events) {
    if (entry.date < todayIso) continue; // vergangen → nicht mehr erzeugen

    const event = buildSingleEvent(group, entry);

    if (group.auto_replace === true && incomingListsEvent(inputItems, event.title, event.start_date)) {
      console.log(`[Manuelle Termine] "${event.title}" am ${event.start_date} übersprungen – andere Quelle liefert den Termin bereits.`);
      continue;
    }

    events.push(event);
  }

  if (!events.length) continue;

  manualItems.push({
    json: {
      source: { ...group.source },
      data: events,
      manual_source: true,
      manual_series_key: group.key
    },
    pairedItem: { item: 0 }
  });
}

return [...inputItems, ...manualItems];

// ============================================================
// Funktionen – Event-Aufbau
// ============================================================

function buildSeriesEvent(series, dateIso) {
  const e = series.event;

  return {
    source_id: series.source.source_id,
    source_name: series.source.source_name,
    title: e.title,
    start_date: dateIso,
    end_date: dateIso,
    start_time: series.start_time,
    end_time: series.end_time || null,
    venue: e.venue,
    location_name: e.location_name,
    address: e.address,
    city: e.city,
    organizer: e.organizer,
    category: e.category,
    short_description: e.short_description,
    url: e.url,
    source_url: e.url,
    confidence: 1,
    review_required: false,
    extraction_notes: e.extraction_notes
  };
}

function buildSingleEvent(group, entry) {
  const e = { ...(group.defaults || {}), ...entry };
  const dateIso = e.date;

  return {
    source_id: group.source.source_id,
    source_name: group.source.source_name,
    title: e.title,
    start_date: dateIso,
    end_date: e.end_date || dateIso,
    start_time: e.start_time,
    end_time: e.end_time || null,
    venue: e.venue,
    location_name: e.location_name,
    address: e.address,
    city: e.city,
    organizer: e.organizer,
    category: e.category,
    short_description: e.short_description,
    url: e.url,
    source_url: e.url,
    confidence: 1,
    review_required: false,
    extraction_notes: e.extraction_notes
  };
}

function buildOccurrenceDates(series, todayIso, horizonEndIso) {
  const fromIso = maxIso(todayIso, series.series_start);
  const toIso = series.series_end ? minIso(horizonEndIso, series.series_end) : horizonEndIso;

  if (fromIso > toIso) return [];

  const excluded = new Set(series.exclude_dates || []);

  let cursor = fromIso;
  let guard = 0;
  while (weekdayOfIso(cursor) !== series.weekday && guard < 7) {
    cursor = addDaysIso(cursor, 1);
    guard++;
  }

  const out = [];
  while (cursor <= toIso) {
    if (!excluded.has(cursor)) out.push(cursor);
    cursor = addDaysIso(cursor, 7);
  }

  return out;
}

// ============================================================
// Funktionen – Auto-Ablösung
// ============================================================

// Serien: Prüft, ob ein eingehendes Item der regulären Quelle den Termin enthält.
function sourceAlreadyListsSeries(items, rule) {
  const markers = (rule.source_markers || []).map((m) => asString(m).toLowerCase()).filter(Boolean);
  const pattern = rule.title_pattern;
  if (!markers.length || !(pattern instanceof RegExp)) return false;

  for (const item of items) {
    let text = '';
    try {
      text = JSON.stringify(item.json || {});
    } catch (error) {
      continue;
    }

    const lower = text.toLowerCase();
    const hasMarker = markers.some((m) => lower.includes(m));
    if (!hasMarker) continue;

    if (pattern.test(text)) return true;
  }

  return false;
}

// Einzeltermine: Sucht in allen eingehenden Items ein Objekt, dessen
// String-Felder den Titel enthalten UND dessen Inhalt das Datum enthält
// (ISO 2026-11-09 oder deutsch 09.11.2026 / 9.11.2026).
function incomingListsEvent(items, title, dateIso) {
  const titleNorm = normalizeForMatch(title);
  if (titleNorm.length < 10) return false; // zu kurz → Fehltreffer-Risiko

  const dateVariants = buildDateVariants(dateIso);

  for (const item of items) {
    if (objectContainsEvent(item.json, titleNorm, dateVariants, 0)) return true;
  }

  return false;
}

function objectContainsEvent(node, titleNorm, dateVariants, depth) {
  if (!node || typeof node !== 'object' || depth > 8) return false;

  if (Array.isArray(node)) {
    return node.some((child) => objectContainsEvent(child, titleNorm, dateVariants, depth + 1));
  }

  const hasTitle = Object.values(node).some(
    (v) => typeof v === 'string' && normalizeForMatch(v).includes(titleNorm)
  );

  if (hasTitle) {
    let text = '';
    try {
      text = JSON.stringify(node);
    } catch (error) {
      text = '';
    }
    if (dateVariants.some((d) => text.includes(d))) return true;
  }

  return Object.values(node).some((child) => objectContainsEvent(child, titleNorm, dateVariants, depth + 1));
}

function buildDateVariants(dateIso) {
  const [y, m, d] = dateIso.split('-');
  return [
    dateIso,                                   // 2026-11-09
    `${d}.${m}.${y}`,                          // 09.11.2026
    `${Number(d)}.${Number(m)}.${y}`           // 9.11.2026
  ];
}

function normalizeForMatch(value) {
  return deAccentLower(value)
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// ============================================================
// Funktionen – Validierung
// ============================================================

function validateSeries(series) {
  const label = `[Manuelle Termine] Serie "${asString(series.key) || '?'}"`;

  if (!series.source || !asString(series.source.source_id)) {
    throw new Error(`${label}: source.source_id fehlt.`);
  }
  if (!series.event || !asString(series.event.title)) {
    throw new Error(`${label}: event.title fehlt.`);
  }
  if (!isIsoDate(series.series_start)) {
    throw new Error(`${label}: series_start "${series.series_start}" ist kein gültiges Datum (YYYY-MM-DD).`);
  }
  if (series.series_end !== null && series.series_end !== undefined && !isIsoDate(series.series_end)) {
    throw new Error(`${label}: series_end "${series.series_end}" ist kein gültiges Datum (YYYY-MM-DD) oder null.`);
  }
  if (!Number.isInteger(series.weekday) || series.weekday < 0 || series.weekday > 6) {
    throw new Error(`${label}: weekday muss 0..6 sein (0=So … 6=Sa).`);
  }
  if (weekdayOfIso(series.series_start) !== series.weekday) {
    throw new Error(`${label}: series_start ${series.series_start} ist kein ${WEEKDAY_NAMES[series.weekday]}.`);
  }
  if (!isHHMM(series.start_time)) {
    throw new Error(`${label}: start_time "${series.start_time}" ist nicht im Format HH:MM.`);
  }
  if (series.end_time && !isHHMM(series.end_time)) {
    throw new Error(`${label}: end_time "${series.end_time}" ist nicht im Format HH:MM.`);
  }
  for (const d of series.exclude_dates || []) {
    if (!isIsoDate(d)) {
      throw new Error(`${label}: exclude_dates enthält ungültiges Datum "${d}".`);
    }
  }

  checkTexts(label, series.event);
}

function validateSingleGroup(group) {
  const label = `[Manuelle Termine] Gruppe "${asString(group.key) || '?'}"`;

  if (!group.source || !asString(group.source.source_id)) {
    throw new Error(`${label}: source.source_id fehlt.`);
  }
  if (!Array.isArray(group.events) || !group.events.length) {
    throw new Error(`${label}: events[] ist leer.`);
  }

  const seen = new Set();

  for (const entry of group.events) {
    const e = { ...(group.defaults || {}), ...entry };
    const eLabel = `${label}, Termin ${asString(e.date) || '?'}`;

    if (!isIsoDate(e.date)) {
      throw new Error(`${eLabel}: date "${e.date}" ist kein gültiges Datum (YYYY-MM-DD).`);
    }
    if (e.end_date && (!isIsoDate(e.end_date) || e.end_date < e.date)) {
      throw new Error(`${eLabel}: end_date "${e.end_date}" ist ungültig oder liegt vor date.`);
    }
    if (!asString(e.title)) {
      throw new Error(`${eLabel}: title fehlt.`);
    }
    if (
      group.expected_weekday !== null &&
      group.expected_weekday !== undefined &&
      weekdayOfIso(e.date) !== group.expected_weekday
    ) {
      throw new Error(
        `${eLabel}: Datum ist ein ${WEEKDAY_NAMES[weekdayOfIso(e.date)]}, erwartet ${WEEKDAY_NAMES[group.expected_weekday]} – Tippfehler?`
      );
    }
    if (!isHHMM(e.start_time)) {
      throw new Error(`${eLabel}: start_time "${e.start_time}" ist nicht im Format HH:MM.`);
    }
    if (e.end_time && !isHHMM(e.end_time)) {
      throw new Error(`${eLabel}: end_time "${e.end_time}" ist nicht im Format HH:MM.`);
    }
    if (e.end_time && (!e.end_date || e.end_date === e.date) && e.end_time <= e.start_time) {
      throw new Error(`${eLabel}: end_time ${e.end_time} liegt nicht nach start_time ${e.start_time}.`);
    }
    if (!/^https:\/\/\S+$/i.test(asString(e.url))) {
      throw new Error(`${eLabel}: url fehlt oder ist keine https-URL.`);
    }

    const dupKey = `${e.date}|${normalizeForMatch(e.title)}`;
    if (seen.has(dupKey)) {
      throw new Error(`${eLabel}: "${e.title}" ist doppelt eingetragen.`);
    }
    seen.add(dupKey);

    checkTexts(eLabel, e);
  }
}

function checkTexts(label, e) {
  const hit = findRecurrenceTrigger([
    e.title,
    e.short_description,
    e.description,
    e.details,
    e.extraction_notes,
    e.notes
  ]);
  if (hit) {
    throw new Error(
      `${label}: Text enthält den Wiederholungs-Trigger "${hit}". ` +
      '„Termine normalisieren" würde die Einzeltermine sonst erneut ab heute projizieren. Bitte umformulieren.'
    );
  }

  const len = asString(e.short_description).length;
  if (len > MAX_SHORT_DESCRIPTION) {
    throw new Error(
      `${label}: short_description hat ${len} Zeichen (max. ${MAX_SHORT_DESCRIPTION}). Bitte kürzen, sonst wird der Text abgeschnitten.`
    );
  }
}

// Trigger analog zu detectRecurrencePattern() in „Termine normalisieren".
// "wochentlich" bewusst ohne Wortgrenze am Ende, damit auch "wöchentliche"
// und "wöchentlichen" erkannt werden.
function findRecurrenceTrigger(texts) {
  const t = deAccentLower(texts.map(asString).join(' '));

  const patterns = [
    /\bjeden\b/,
    /\b(?:montags|dienstags|mittwochs|donnerstags|freitags|samstags|sonntags|sonnabends)\b/,
    /\bwochentlich/
  ];

  for (const re of patterns) {
    const m = t.match(re);
    if (m) return m[0];
  }

  return '';
}

// ============================================================
// Funktionen – Hilfsfunktionen
// ============================================================

function deAccentLower(value) {
  return asString(value)
    .toLowerCase()
    .replace(/ä/g, 'a')
    .replace(/ö/g, 'o')
    .replace(/ü/g, 'u')
    .replace(/ß/g, 'ss');
}

function getTodayIsoInTimeZone(timeZone) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date());

  const year = parts.find((p) => p.type === 'year')?.value;
  const month = parts.find((p) => p.type === 'month')?.value;
  const day = parts.find((p) => p.type === 'day')?.value;

  return `${year}-${month}-${day}`;
}

function isIsoDate(value) {
  const text = asString(value);
  const m = text.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return false;

  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  const date = new Date(Date.UTC(year, month - 1, day));

  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

function isHHMM(value) {
  const m = asString(value).match(/^(\d{2}):(\d{2})$/);
  if (!m) return false;
  const h = Number(m[1]);
  const min = Number(m[2]);
  return h >= 0 && h <= 23 && min >= 0 && min <= 59;
}

function weekdayOfIso(isoDate) {
  const [year, month, day] = isoDate.split('-').map(Number);
  return new Date(Date.UTC(year, month - 1, day)).getUTCDay();
}

function addDaysIso(isoDate, daysToAdd) {
  const [year, month, day] = isoDate.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  date.setUTCDate(date.getUTCDate() + daysToAdd);
  return formatIsoDate(date);
}

function formatIsoDate(date) {
  return [
    date.getUTCFullYear(),
    pad2(date.getUTCMonth() + 1),
    pad2(date.getUTCDate())
  ].join('-');
}

function maxIso(a, b) {
  return a >= b ? a : b;
}

function minIso(a, b) {
  return a <= b ? a : b;
}

function asString(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function pad2(value) {
  return String(value).padStart(2, '0');
}

// ============================================================================
// Node:    „OpenData Serienfelder ergänzen“
// Typ:     Code-Node, Modus „Run Once for All Items“, Sprache JavaScript
// Ort:     Workflow „1 – Coerde Termine ermitteln“,
//          direkt NACH „Build GitHub OpenData Payloads“, VOR dem GitHub-Upload
//
// Zweck:   Ergänzt die fünf Serienfelder im öffentlichen Export, ohne den
//          Builder anzufassen. Der Node nimmt die Payload-Items des Builders
//          (repo_path + content_b64), dekodiert sie, fügt die Felder ein und
//          kodiert sie wieder. Alle übrigen Felder der Items bleiben unverändert.
//
//   data/events.json     jedes Event erhält am Ende:
//                        series_id, series_type, is_recurring, series_label, series_count
//   data/events.csv      fünf neue Spalten am Zeilenende (bestehende Zeichen bleiben gleich)
//   data/events.ics      pro VEVENT vor END:VEVENT:
//                        X-COERDE-SERIES-ID, X-COERDE-SERIES-TYPE, X-COERDE-IS-RECURRING,
//                        X-COERDE-SERIES-LABEL, X-COERDE-SERIES-COUNT
//                        (IS-RECURRING immer, die übrigen nur bei Serienterminen)
//   data/events.geojson  properties jedes Features (Zuordnung über event_id)
//
// Werte:   series_type  weekly | biweekly | monthly | block | irregular | ""
//          is_recurring "ja" | "nein"   ("ja" nur bei weekly/biweekly/monthly)
//          series_count Zahl im JSON/GeoJSON, sonst Text; "" bzw. null = kein Serientermin
//
// WICHTIG: Die Serienerkennung ist identisch mit dem Node „Serientermine
//          kennzeichnen“ in Workflow 2. Gleiche Termine bekommen dadurch in Sheet
//          und Open Data dieselbe series_id. Änderungen an CONFIG (v. a.
//          MANUAL_SERIES) deshalb immer in BEIDEN Nodes gleich vornehmen.
//          series_count/series_type können trotzdem leicht abweichen, weil
//          Workflow 1 einen anderen Terminbestand exportiert als events_current.
//
// Hinweise:
//   - Läuft in der Task-Runner-Sandbox: keine URL-Klasse, kein require().
//     Base64 nutzt Buffer, falls vorhanden, sonst eine eingebaute Umsetzung.
//   - Mehrfaches Ausführen ist unschädlich: vorhandene Serienfelder werden ersetzt,
//     nicht doppelt angehängt.
// ============================================================================

const CONFIG = {
  // ---- Serienerkennung: identisch zu „Serientermine kennzeichnen“ (Workflow 2) ----
  RECURRING_TYPES: ['weekly', 'biweekly', 'monthly'],
  USE_TEXT_SIGNALS_FOR_SINGLES: true,
  BLOCK_MAX_GAP_DAYS: 3,
  DOMINANT_WEEKDAY_SHARE: 0.7,
  YES: 'ja',
  NO: 'nein',
  INCLUDE_DEBUG_KEY: false,
  MANUAL_SERIES: [
    // Stadt Münster: jede Workshop-Folge hat eigenen Titel + eigene eventInfoId
    { title: /^Smartphone-Workshop für ältere Menschen\s*\|\s*Coerde/i, name: 'smartphone-workshop-coerde' },
  ],

  // ---- Export ----
  FIELDS: ['series_id', 'series_type', 'is_recurring', 'series_label', 'series_count'],
  ICS_PREFIX: 'X-COERDE-',
  ICS_UID_SUFFIX: '@coerde-events',
  // Item-Felder des Builders (laut SETUP.md und Spalten in events_review)
  PATH_KEYS: ['repo_path', 'path', 'file_path'],
  CONTENT_KEY: 'content_b64',
};

// ---------------------------------------------------------------------------
// Hilfsfunktionen: Felder lesen
// ---------------------------------------------------------------------------
// Liest das erste nicht-leere Feld aus der Liste. Groß-/Kleinschreibung und
// Leerzeichen am Rand des Spaltennamens werden ignoriert ("URL" = "url").
function pick(obj, keys) {
  const lower = {};
  for (const k of Object.keys(obj)) lower[k.trim().toLowerCase()] = obj[k];
  for (const k of keys) {
    const v = lower[k.toLowerCase()];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return '';
}

// Spaltennamen im Sheet events_current/events_review (deutsch) zuerst,
// danach die englischen Namen aus dem Open-Data-Schema
const getTitle = (j) => String(pick(j, ['Titel', 'title', 'name', 'summary']));
const getSourceId = (j) => String(pick(j, ['source_id', 'sourceId', 'source']));
const getUrl = (j) => String(pick(j, ['URL', 'source_url', 'event_url', 'link']));
const getDescription = (j) =>
  String(pick(j, ['Kurzbeschreibung', 'short_description', 'description', 'beschreibung']));

// Datum → "YYYY-MM-DD" (akzeptiert ISO, ISO mit Uhrzeit, DD.MM.YYYY,
// Google-Sheets-Seriennummer)
function toIsoDate(v) {
  if (v === undefined || v === null || v === '') return '';
  if (typeof v === 'number' && isFinite(v) && v > 20000 && v < 80000) {
    const ms = Math.round((v - 25569) * 86400000); // Sheets-Epoche 1899-12-30
    return new Date(ms).toISOString().slice(0, 10);
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  if (/^\d{5}(\.\d+)?$/.test(s)) return toIsoDate(Number(s));
  return '';
}

// Uhrzeit → "HH:MM" oder "" (ganztägig/unbekannt)
function toTime(v) {
  if (v === undefined || v === null || v === '') return '';
  if (typeof v === 'number' && v >= 0 && v < 1) {
    const mins = Math.round(v * 1440);
    return `${String(Math.floor(mins / 60)).padStart(2, '0')}:${String(mins % 60).padStart(2, '0')}`;
  }
  const m = String(v).trim().match(/^(\d{1,2})[:.](\d{2})/);
  return m ? `${m[1].padStart(2, '0')}:${m[2]}` : '';
}

const getDate = (j) => toIsoDate(pick(j, ['date_start', 'start_date', 'startDate', 'Datum', 'date']));
const getTime = (j) => toTime(pick(j, ['time_start', 'start_time', 'startTime', 'Uhrzeit']));

// ---------------------------------------------------------------------------
// Hilfsfunktionen: Text, Hash, Datum
// ---------------------------------------------------------------------------
function normText(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

// FNV-1a 32 Bit, zweimal mit unterschiedlichem Startwert → 12 Hex-Zeichen
function fnv1a(str, seed) {
  let h = seed >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}
const makeSeriesId = (key) =>
  'ser_' + (fnv1a(key, 0x811c9dc5) + fnv1a(key, 0x9e3779b9)).slice(0, 12);

const WD_ADVERB = ['sonntags', 'montags', 'dienstags', 'mittwochs', 'donnerstags', 'freitags', 'samstags'];
const WD_NOUN = ['Sonntag', 'Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag'];
const WD_ORDER = [1, 2, 3, 4, 5, 6, 0]; // Mo … So für die Ausgabe

function parseIso(iso) {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d));
}
const weekday = (iso) => parseIso(iso).getUTCDay();
const dayDiff = (a, b) => Math.round((parseIso(b) - parseIso(a)) / 86400000);
function nthOfMonth(iso) {
  const d = parseIso(iso);
  const day = d.getUTCDate();
  const dim = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
  return { nth: Math.ceil(day / 7), isLast: day + 7 > dim };
}
function fmtDate(iso, withYear) {
  const [y, m, d] = iso.split('-');
  return withYear ? `${d}.${m}.${y}` : `${d}.${m}.`;
}
function joinDe(list) {
  if (list.length <= 1) return list.join('');
  return list.slice(0, -1).join(', ') + ' und ' + list[list.length - 1];
}
const weekdaysLabel = (wds) =>
  joinDe(WD_ORDER.filter((w) => wds.includes(w)).map((w) => WD_ADVERB[w]));

// ---------------------------------------------------------------------------
// Serien-Schlüssel
// ---------------------------------------------------------------------------
function seriesKey(j) {
  const url = getUrl(j);

  // 0) Manuelle Serien aus CONFIG.MANUAL_SERIES
  const rawTitle = getTitle(j);
  const srcNorm = normText(getSourceId(j));
  for (const r of CONFIG.MANUAL_SERIES) {
    if (r.source_id && normText(r.source_id) !== srcNorm) continue;
    if (r.title && r.title.test(rawTitle)) return `man|${r.name}`;
  }

  // 1) FaBi / KuferWeb-Kursnummer: …/kurssuche/kurs/<slug>/<kursnr>
  let m = url.match(/\/kurssuche\/kurs\/[^\/?#]+\/([A-Za-z0-9][A-Za-z0-9.\-]*)\/?(?:[?#]|$)/i);
  if (m) return `kurs|${(url.match(/^https?:\/\/([^\/?#]+)/i) || [, ''])[1].toLowerCase()}|${m[1]}`;

  // 2) Stadt Münster Veranstaltungskalender: …/detail/<eventInfoId>/<eventDateId>
  m = url.match(/stadt-muenster\.de\/veranstaltungskalender\/-\/detail\/(\d+)\/\d+/i);
  if (m) return `smk|${m[1]}`;

  // 3) Generisch
  const title = normText(getTitle(j));
  if (!title) return '';
  return `gen|${normText(getSourceId(j))}|${title}|${getTime(j) || 'ganztag'}`;
}

// ---------------------------------------------------------------------------
// Klassifikation aus den Daten (>= 2 verschiedene Daten)
// ---------------------------------------------------------------------------
function classifySameWeekday(dates) {
  // dates: sortiert, eindeutig, alle derselbe Wochentag, Länge >= 2
  const diffs = dates.slice(1).map((d, i) => dayDiff(dates[i], d));
  const minDiff = Math.min(...diffs);
  const ords = dates.map(nthOfMonth);

  if (minDiff === 7 && diffs.every((x) => x % 7 === 0)) return { type: 'weekly' };
  if (diffs.every((x) => x === 14)) return { type: 'biweekly' };

  // monatlich, eine Ordnungszahl (z. B. jeden 3. Freitag / jeden letzten Sonntag)
  if (diffs.every((x) => x === 28 || x === 35)) {
    if (ords.every((o) => o.nth === ords[0].nth)) return { type: 'monthly', ords: [ords[0].nth] };
    if (ords.every((o) => o.isLast)) return { type: 'monthly', ords: ['last'] };
  }
  // monatlich, zwei Ordnungszahlen (z. B. 2. und 4. Montag) – erst ab 3 Terminen
  const nthSet = [...new Set(ords.map((o) => o.nth))].sort();
  if (dates.length >= 3 && nthSet.length === 2 && diffs.every((x) => x >= 14 && x <= 21)) {
    return { type: 'monthly', ords: nthSet };
  }
  if (minDiff >= 14 && diffs.every((x) => x % 14 === 0)) return { type: 'biweekly' };
  return { type: 'irregular' };
}

function classify(dates) {
  const n = dates.length;
  const diffs = dates.slice(1).map((d, i) => dayDiff(dates[i], d));
  const first = dates[0];
  const last = dates[n - 1];
  const sameYear = first.slice(0, 4) === last.slice(0, 4);
  const range = `${fmtDate(first, !sameYear)}–${fmtDate(last, true)}`;

  // Block: dicht aufeinanderfolgende Tage
  if (diffs.every((x) => x <= CONFIG.BLOCK_MAX_GAP_DAYS)) {
    const daily = diffs.every((x) => x === 1);
    return {
      type: 'block',
      label: daily ? `täglich, ${range}` : `an ${n} Tagen, ${range}`,
    };
  }

  // Nach Wochentag aufteilen
  const byWd = {};
  for (const d of dates) (byWd[weekday(d)] = byWd[weekday(d)] || []).push(d);
  const wds = Object.keys(byWd).map(Number);

  // Kurs mit wenigen Zusatzterminen (z. B. mittwochs + ein Wald-Wochenende):
  // dominanter Wochentag trägt das Muster, Rest wird als Zusatztermine genannt
  const domWd = wds.reduce((a, b) => (byWd[b].length > byWd[a].length ? b : a), wds[0]);
  const domDates = byWd[domWd];
  if (wds.length > 1 && domDates.length >= 3 && domDates.length / n >= CONFIG.DOMINANT_WEEKDAY_SHARE) {
    const r = classifySameWeekday(domDates);
    const extra = n - domDates.length;
    const extraTxt = ` (+${extra} Zusatztermin${extra === 1 ? '' : 'e'})`;
    if (r.type === 'weekly') return { type: 'weekly', label: `wöchentlich, ${WD_ADVERB[domWd]}${extraTxt}` };
    if (r.type === 'biweekly') return { type: 'biweekly', label: `alle 2 Wochen, ${WD_ADVERB[domWd]}${extraTxt}` };
  }

  if (wds.every((w) => byWd[w].length >= 2)) {
    const results = wds.map((w) => classifySameWeekday(byWd[w]));
    const t = results[0].type;
    const sameType = results.every((r) => r.type === t);
    if (sameType && t === 'weekly') {
      return { type: 'weekly', label: `wöchentlich, ${weekdaysLabel(wds)}` };
    }
    if (sameType && t === 'biweekly') {
      return { type: 'biweekly', label: `alle 2 Wochen, ${weekdaysLabel(wds)}` };
    }
    if (sameType && t === 'monthly' && wds.length === 1) {
      const o = results[0].ords;
      const ordTxt = o[0] === 'last' ? 'letzten' : o.map((x) => `${x}.`).join(' und ');
      return { type: 'monthly', label: `monatlich, jeden ${ordTxt} ${WD_NOUN[wds[0]]}` };
    }
  }
  return { type: 'irregular', label: `mehrere Termine (${n}), ${range}` };
}

// ---------------------------------------------------------------------------
// Textsignale für Einzeltermine
// ---------------------------------------------------------------------------
const WD_RE = '(montag|dienstag|mittwoch|donnerstag|freitag|samstag|sonntag)';
const ORD_RE = '(ersten|zweiten|dritten|vierten|fuenften|letzten|[1-5]\\.)';
const WD_INDEX = { sonntag: 0, montag: 1, dienstag: 2, mittwoch: 3, donnerstag: 4, freitag: 5, samstag: 6 };
const ORD_INDEX = { ersten: 1, zweiten: 2, dritten: 3, vierten: 4, fuenften: 5, letzten: 'last' };
const ordVal = (s) => (ORD_INDEX[s] !== undefined ? ORD_INDEX[s] : Number(String(s).replace('.', '')));

// Umlaute vereinheitlichen, Satzzeichen wie "2." erhalten
const searchText = (j) =>
  `${getTitle(j)} ${getDescription(j)}`
    .toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .replace(/\s+/g, ' ');

// Monatsmuster mit Ordnungszahl. Gilt nur als Wiederholung bei
// "jeden/jedem ersten Donnerstag" oder "… Donnerstag im Monat / des Monats".
// "am ersten Sonntag im November" ist ein Einzeltermin und zählt nicht.
const RE_ORD_JEDEN = new RegExp(
  `(?:jeden|jedem)\\s+${ORD_RE}\\s*(?:(?:und|&|u\\.)\\s*${ORD_RE}\\s*)?${WD_RE}`
);
const RE_ORD_IM_MONAT = new RegExp(
  `${ORD_RE}\\s*(?:(?:und|&|u\\.)\\s*${ORD_RE}\\s*)?${WD_RE}\\s+(?:im|des|eines|jedes)\\s+monats?\\b`
);
const RE_JEDEN_WD = new RegExp(`\\bjeden\\s+${WD_RE}`);

// Wochentage, die der Text ausdrücklich als Wiederholung nennt (für Plausibilitätsprüfung)
function textWeekdays(j) {
  const txt = searchText(j);
  const found = new Set();
  for (const re of [RE_ORD_JEDEN, RE_ORD_IM_MONAT]) {
    const m = txt.match(re);
    if (m) found.add(WD_INDEX[m[3]]);
  }
  const m = txt.match(RE_JEDEN_WD);
  if (m) found.add(WD_INDEX[m[1]]);
  return [...found];
}

function textSignal(j, iso) {
  const txt = searchText(j);
  const wdOfDate = weekday(iso);
  const pos = nthOfMonth(iso);

  // monatlich mit Ordnungszahl
  let m = txt.match(RE_ORD_JEDEN) || txt.match(RE_ORD_IM_MONAT);
  if (m) {
    const o1 = ordVal(m[1]);
    const o2 = m[2] ? ordVal(m[2]) : null;
    const wd = WD_INDEX[m[3]];
    const fits = (o) => (o === 'last' ? pos.isLast : o === pos.nth);
    if (wd === wdOfDate && (fits(o1) || (o2 !== null && fits(o2)))) {
      const ordTxt = [o1, o2]
        .filter((o) => o !== null)
        .map((o) => (o === 'last' ? 'letzten' : `${o}.`))
        .join(' und ');
      return { type: 'monthly', label: `monatlich, jeden ${ordTxt} ${WD_NOUN[wd]}` };
    }
    return null; // Text nennt ein Muster, das nicht zum Datum passt → nicht raten
  }

  if (/\bmonatlich|\bjeden monat\b|\beinmal im monat\b/.test(txt)) {
    return { type: 'monthly', label: 'monatlich' };
  }

  if (/14-taegig|vierzehntaegig|zweiwoechentlich|alle (zwei|2) wochen/.test(txt)) {
    return { type: 'biweekly', label: `alle 2 Wochen, ${WD_ADVERB[wdOfDate]}` };
  }

  // wöchentlich: "jeden Freitag" / "wöchentlich"
  m = txt.match(RE_JEDEN_WD);
  if (m) {
    return WD_INDEX[m[1]] === wdOfDate
      ? { type: 'weekly', label: `wöchentlich, ${WD_ADVERB[wdOfDate]}` }
      : null;
  }
  if (/\bwoechentlich|\bjede woche\b/.test(txt)) {
    return { type: 'weekly', label: `wöchentlich, ${WD_ADVERB[wdOfDate]}` };
  }
  return null;
}

// ---------------------------------------------------------------------------
// Serienfelder für eine Liste von Events berechnen → Map event_id → Felder
// (gleiche Logik wie die Hauptlogik in „Serientermine kennzeichnen“)
// ---------------------------------------------------------------------------
function emptyFields() {
  return { series_id: '', series_type: '', is_recurring: CONFIG.NO, series_label: '', series_count: '' };
}

function computeSeries(events) {
  const groups = new Map();
  const keys = events.map((ev) => {
    const iso = getDate(ev);
    const key = iso ? seriesKey(ev) : '';
    if (key) {
      if (!groups.has(key)) groups.set(key, { dates: new Set(), first: ev });
      groups.get(key).dates.add(iso);
    }
    return key;
  });

  const info = new Map();
  const warnings = [];
  for (const [key, g] of groups) {
    const dates = [...g.dates].sort();
    if (dates.length >= 2) {
      const c = classify(dates);
      info.set(key, {
        series_id: makeSeriesId(key),
        series_type: c.type,
        series_label: c.label,
        series_count: dates.length,
      });
      const named = textWeekdays(g.first);
      const actual = new Set(dates.map(weekday));
      if (named.some((w) => !actual.has(w))) {
        warnings.push(
          `${getTitle(g.first)} (${getSourceId(g.first)}): Text nennt ` +
            `${named.map((w) => WD_NOUN[w]).join('/')}, Termine liegen ${weekdaysLabel([...actual])}`
        );
      }
    }
  }

  const byEventId = new Map();
  const stats = {};
  events.forEach((ev, i) => {
    const key = keys[i];
    let s = key ? info.get(key) : undefined;
    if (!s && key && CONFIG.USE_TEXT_SIGNALS_FOR_SINGLES) {
      const sig = textSignal(ev, getDate(ev));
      if (sig) s = { series_id: makeSeriesId(key), series_type: sig.type, series_label: sig.label, series_count: 1 };
    }
    const f = s
      ? {
          series_id: s.series_id,
          series_type: s.series_type,
          is_recurring: CONFIG.RECURRING_TYPES.includes(s.series_type) ? CONFIG.YES : CONFIG.NO,
          series_label: s.series_label,
          series_count: s.series_count,
        }
      : emptyFields();
    if (CONFIG.INCLUDE_DEBUG_KEY) f.series_key = key;
    stats[f.series_type || 'einzel'] = (stats[f.series_type || 'einzel'] || 0) + 1;
    const id = String(ev.event_id || '').trim();
    if (id) byEventId.set(id, f);
  });
  return { byEventId, stats, warnings };
}

// ---------------------------------------------------------------------------
// Base64 / UTF-8 (Buffer, falls verfügbar; sonst eigene Umsetzung)
// ---------------------------------------------------------------------------
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

function utf8Encode(str) {
  const out = [];
  for (const ch of str) {
    let cp = ch.codePointAt(0);
    if (cp < 0x80) out.push(cp);
    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 63));
    else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    else out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
  }
  return out;
}

function utf8Decode(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; ) {
    const b = bytes[i];
    let cp;
    if (b < 0x80) { cp = b; i += 1; }
    else if (b < 0xe0) { cp = ((b & 31) << 6) | (bytes[i + 1] & 63); i += 2; }
    else if (b < 0xf0) { cp = ((b & 15) << 12) | ((bytes[i + 1] & 63) << 6) | (bytes[i + 2] & 63); i += 3; }
    else { cp = ((b & 7) << 18) | ((bytes[i + 1] & 63) << 12) | ((bytes[i + 2] & 63) << 6) | (bytes[i + 3] & 63); i += 4; }
    out += String.fromCodePoint(cp);
  }
  return out;
}

function b64decode(b64) {
  const clean = String(b64 || '').replace(/[^A-Za-z0-9+/=]/g, '');
  if (typeof Buffer !== 'undefined') return Buffer.from(clean, 'base64').toString('utf8');
  const bytes = [];
  for (let i = 0; i < clean.length; i += 4) {
    const n = [0, 1, 2, 3].map((k) => (clean[i + k] === '=' || clean[i + k] === undefined ? -1 : B64.indexOf(clean[i + k])));
    bytes.push((n[0] << 2) | (n[1] >> 4));
    if (n[2] >= 0) bytes.push(((n[1] & 15) << 4) | (n[2] >> 2));
    if (n[3] >= 0) bytes.push(((n[2] & 3) << 6) | n[3]);
  }
  return utf8Decode(bytes);
}

function b64encode(str) {
  if (typeof Buffer !== 'undefined') return Buffer.from(str, 'utf8').toString('base64');
  const bytes = utf8Encode(str);
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const [a, b, c] = [bytes[i], bytes[i + 1], bytes[i + 2]];
    out += B64[a >> 2] + B64[((a & 3) << 4) | ((b ?? 0) >> 4)];
    out += b === undefined ? '=' : B64[((b & 15) << 2) | ((c ?? 0) >> 6)];
    out += c === undefined ? '=' : B64[c & 63];
  }
  return out;
}

const utf8Length = (s) => utf8Encode(s).length;
const detectEol = (text) => (text.includes('\r\n') ? '\r\n' : '\n');

// ---------------------------------------------------------------------------
// JSON
// ---------------------------------------------------------------------------
function getEventList(obj) {
  if (Array.isArray(obj)) return obj;
  if (obj && Array.isArray(obj.events)) return obj.events;
  return null;
}

function jsonValue(f, name) {
  // Zahl bleibt Zahl, leere Anzahl wird null
  if (name === 'series_count') return f.series_count === '' ? null : Number(f.series_count);
  return f[name];
}

function patchJson(text, fieldsById) {
  const obj = JSON.parse(text);
  const events = getEventList(obj) || [];
  let n = 0;
  for (const ev of events) {
    const f = fieldsById.get(String(ev.event_id || '').trim()) || emptyFields();
    for (const name of CONFIG.FIELDS) ev[name] = jsonValue(f, name);
    n++;
  }
  return { text: JSON.stringify(obj, null, 2) + (text.endsWith('\n') ? '\n' : ''), count: n };
}

// ---------------------------------------------------------------------------
// CSV (Originalzeilen bleiben Zeichen für Zeichen erhalten, Spalten werden angehängt)
// ---------------------------------------------------------------------------
function splitCsvRecords(text) {
  const recs = [];
  let start = 0;
  let inQ = false;
  let field = '';
  let fields = [];
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQ) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; }
        else inQ = false;
      } else field += c;
    } else if (c === '"') inQ = true;
    else if (c === ',') { fields.push(field); field = ''; }
    else if (c === '\r' || c === '\n') {
      fields.push(field);
      recs.push({ raw: text.slice(start, i), fields });
      if (c === '\r' && text[i + 1] === '\n') i++;
      field = '';
      fields = [];
      start = i + 1;
    } else field += c;
  }
  if (start < text.length) {
    fields.push(field);
    recs.push({ raw: text.slice(start), fields });
  }
  return recs;
}

const csvCell = (v) => {
  const s = v === undefined || v === null ? '' : String(v);
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

function patchCsv(text, fieldsById) {
  const eol = detectEol(text);
  const recs = splitCsvRecords(text);
  if (!recs.length) return { text, count: 0 };
  const header = recs[0].fields.map((h) => h.trim());
  if (header.includes('series_id')) {
    // bereits ergänzt (z. B. zweiter Lauf) → Spalten neu schreiben wäre aufwendig; unverändert lassen
    return { text, count: 0, skipped: 'Spalten schon vorhanden' };
  }
  const idCol = Math.max(0, header.indexOf('event_id'));
  let n = 0;
  const out = recs.map((r, idx) => {
    if (r.raw === '') return r.raw;
    if (idx === 0) return r.raw + ',' + CONFIG.FIELDS.join(',');
    const f = fieldsById.get(String(r.fields[idCol] || '').trim()) || emptyFields();
    n++;
    return r.raw + ',' + CONFIG.FIELDS.map((name) => csvCell(f[name])).join(',');
  });
  return { text: out.join(eol) + (/\r?\n$/.test(text) ? eol : ''), count: n };
}

// ---------------------------------------------------------------------------
// ICS (RFC 5545: TEXT-Escaping, Zeilenfaltung bei 75 Oktetten)
// ---------------------------------------------------------------------------
const icsText = (s) =>
  String(s).replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n');

function foldIcsLine(line) {
  if (utf8Length(line) <= 75) return [line];
  const parts = [];
  let cur = '';
  let curLen = 0;
  let limit = 75;
  for (const ch of line) {
    const l = utf8Length(ch);
    if (curLen + l > limit) {
      parts.push(cur);
      cur = ' ';
      curLen = 1;
      limit = 75;
    }
    cur += ch;
    curLen += l;
  }
  parts.push(cur);
  return parts;
}

function icsSeriesLines(f) {
  const P = CONFIG.ICS_PREFIX;
  const lines = [];
  if (f.series_id) lines.push(`${P}SERIES-ID:${icsText(f.series_id)}`);
  if (f.series_type) lines.push(`${P}SERIES-TYPE:${icsText(f.series_type)}`);
  lines.push(`${P}IS-RECURRING:${icsText(f.is_recurring || CONFIG.NO)}`);
  if (f.series_label) lines.push(`${P}SERIES-LABEL:${icsText(f.series_label)}`);
  if (f.series_count !== '' && f.series_count !== undefined) lines.push(`${P}SERIES-COUNT:${f.series_count}`);
  return lines.flatMap(foldIcsLine);
}

function patchIcs(text, fieldsById) {
  const eol = detectEol(text);
  const lines = text.split(/\r?\n/);
  const trailing = lines.length && lines[lines.length - 1] === '' ? lines.pop() : null;
  const out = [];
  let inEvent = false;
  let uid = '';
  let collectingUid = false;
  let skipping = false; // eigene Zeilen aus einem früheren Lauf überspringen
  let n = 0;
  let matched = 0;
  const P = CONFIG.ICS_PREFIX;
  const ownProp = new RegExp(`^${P}(SERIES-ID|SERIES-TYPE|IS-RECURRING|SERIES-LABEL|SERIES-COUNT)[;:]`, 'i');

  for (const line of lines) {
    const isCont = line.startsWith(' ') || line.startsWith('\t');
    if (skipping) {
      if (isCont) continue;
      skipping = false;
    }
    if (collectingUid) {
      if (isCont) { uid += line.slice(1); out.push(line); continue; }
      collectingUid = false;
    }
    if (line === 'BEGIN:VEVENT') { inEvent = true; uid = ''; }
    if (inEvent && /^UID[;:]/i.test(line)) {
      uid = line.slice(line.indexOf(':') + 1);
      collectingUid = true;
    }
    if (inEvent && ownProp.test(line)) { skipping = true; continue; }
    if (line === 'END:VEVENT' && inEvent) {
      const id = uid.endsWith(CONFIG.ICS_UID_SUFFIX) ? uid.slice(0, -CONFIG.ICS_UID_SUFFIX.length) : uid;
      const f = fieldsById.get(id.trim());
      if (f) matched++;
      out.push(...icsSeriesLines(f || emptyFields()));
      inEvent = false;
      n++;
    }
    out.push(line);
  }
  if (trailing !== null) out.push(trailing);
  return { text: out.join(eol), count: n, matched };
}

// ---------------------------------------------------------------------------
// GeoJSON
// ---------------------------------------------------------------------------
function patchGeojson(text, fieldsById) {
  const obj = JSON.parse(text);
  const feats = Array.isArray(obj.features) ? obj.features : [];
  let n = 0;
  for (const ft of feats) {
    ft.properties = ft.properties || {};
    const f = fieldsById.get(String(ft.properties.event_id || ft.id || '').trim());
    if (!f) continue;
    for (const name of CONFIG.FIELDS) ft.properties[name] = jsonValue(f, name);
    n++;
  }
  return { text: n ? JSON.stringify(obj, null, 2) + (text.endsWith('\n') ? '\n' : '') : text, count: n };
}

// ---------------------------------------------------------------------------
// Hauptlogik
// ---------------------------------------------------------------------------
const items = $input.all();
const pathOf = (j) => String(pick(j, CONFIG.PATH_KEYS)).toLowerCase();
const kindOf = (p) =>
  p.endsWith('.geojson') ? 'geojson' : p.endsWith('.json') ? 'json' : p.endsWith('.csv') ? 'csv' : p.endsWith('.ics') ? 'ics' : '';

const report = [];
const jsonItem = items.find((it) => kindOf(pathOf(it.json || {})) === 'json' && (it.json || {})[CONFIG.CONTENT_KEY]);

if (!jsonItem) {
  console.log(
    'OpenData Serienfelder ergänzen – WARNUNG: kein events.json-Item gefunden, nichts geändert. Vorhandene Pfade: ' +
      items.map((it) => pathOf(it.json || {}) || '(ohne Pfad)').join(', ')
  );
  return items.map((it, i) => ({ json: it.json, pairedItem: { item: i } }));
}

const sourceEvents = getEventList(JSON.parse(b64decode(jsonItem.json[CONFIG.CONTENT_KEY]))) || [];
const { byEventId, stats, warnings } = computeSeries(sourceEvents);

const out = items.map((it, i) => {
  const j = it.json || {};
  const kind = kindOf(pathOf(j));
  const b64 = j[CONFIG.CONTENT_KEY];
  if (!kind || !b64) return { json: j, pairedItem: { item: i } };

  try {
    const text = b64decode(b64);
    const res =
      kind === 'json' ? patchJson(text, byEventId)
      : kind === 'csv' ? patchCsv(text, byEventId)
      : kind === 'ics' ? patchIcs(text, byEventId)
      : patchGeojson(text, byEventId);
    report.push(`${pathOf(j)}: ${res.count} Einträge${res.matched !== undefined ? `, ${res.matched} zugeordnet` : ''}${res.skipped ? ` (${res.skipped})` : ''}`);
    return { json: { ...j, [CONFIG.CONTENT_KEY]: b64encode(res.text) }, pairedItem: { item: i } };
  } catch (e) {
    // Im Fehlerfall Original unverändert weitergeben, damit der Upload nicht scheitert
    report.push(`${pathOf(j)}: FEHLER ${e.message} – Original unverändert`);
    return { json: j, pairedItem: { item: i } };
  }
});

console.log('OpenData Serienfelder ergänzen – Verteilung:', JSON.stringify(stats));
console.log('OpenData Serienfelder ergänzen – Dateien:\n' + report.join('\n'));
if (warnings.length) console.log('OpenData Serienfelder ergänzen – Text passt nicht zu den Terminen:\n' + warnings.join('\n'));
return out;

// ============================================================================
// Node:    „Quellen-Gesundheit prüfen“
// Typ:     Code-Node, Modus „Run Once for All Items“, Sprache JavaScript
// Ort:     Workflow „1 – Coerde Termine ermitteln“, als zusätzlicher Zweig an
//          „Letzte Korrekturen“ (parallel zu „Build GitHub OpenData Payloads“
//          und „events_review bereinigen“). Danach folgt ein Send-Email-Node.
// Stand:   26.11.2026
//          Änderung: ALWAYS_REPORT wieder auf false (war seit dem Test aktiv).
//          Ohne Befund gibt der Node kein Item aus, „Warnmail Quellen“ läuft
//          dann nicht – es kommt also nur noch bei einem Befund eine Mail.
//
// Zweck:   Erkennt, wenn eine Quelle plötzlich keine oder deutlich weniger
//          Termine liefert (z. B. Andreas-Kirchengemeinde 29.09.–13.10.2026:
//          drei Wochen lang 0 Termine, ohne dass es auffiel).
//
// Vorgehen:
//   1. Termine dieses Laufs je source_id zählen – nur noch anstehende Termine
//      (Ende >= heute) und ohne publish = nein.
//   2. Die letzten CONFIG.BASELINE_RUNS veröffentlichten Stände von
//      data/events.json aus GitHub laden (öffentlich, kein Token nötig).
//      Stände, die jünger als CONFIG.SKIP_RECENT_MINUTES sind, werden
//      übersprungen – damit vergleicht der Node nie mit dem eigenen Lauf,
//      egal in welcher Reihenfolge n8n die Zweige ausführt.
//   3. Auch in den alten Ständen zählen nur Termine, die HEUTE noch anstehen.
//      Ein Semester- oder Saisonende (alle Termine vorbei) löst deshalb
//      keinen Alarm aus.
//   4. Erwartung je Quelle = höchster Wert der alten Stände.
//      - Ausfall:  Erwartung >= MIN_EXPECTED und jetzt 0 Termine
//      - Einbruch: jetzt < Erwartung × DROP_RATIO und Differenz >= MIN_ABS_DROP
//      - Gesamt:   alle Quellen zusammen < Erwartung × TOTAL_DROP_RATIO
//
// Ausgabe:
//   - Alles in Ordnung: KEIN Item → der nachfolgende Send-Email-Node läuft nicht.
//   - Auffälligkeit: genau EIN Item mit subject, text, html, problems, table.
//   - Fehler beim Abruf von GitHub: Log-Eintrag; Mail nur, wenn
//     CONFIG.NOTIFY_ON_CHECK_ERROR = true. Der Node wirft nie einen Fehler,
//     damit der eigentliche Workflow nicht abbricht.
//
// Hinweise:
//   - Läuft in der Task-Runner-Sandbox: keine URL-Klasse, kein require();
//     HTTP über this.helpers.httpRequest.
//   - GitHub-API ohne Token: 60 Abrufe pro Stunde und IP. Der Node braucht
//     1 API-Abruf (Commit-Liste) + BASELINE_RUNS Abrufe von raw.githubusercontent.com.
//   - Fällt eine Quelle dauerhaft aus, kommt höchstens BASELINE_RUNS-mal eine
//     Mail – danach ist die 0 der neue Normalzustand.
// ============================================================================

const CONFIG = {
  REPO: 'Coerdeevents/coerde-events',
  BRANCH: 'main',
  FILE_PATH: 'data/events.json',
  TIMEZONE: 'Europe/Berlin',

  BASELINE_RUNS: 3,            // so viele frühere Läufe als Vergleich
  SKIP_RECENT_MINUTES: 45,     // jüngere Commits ignorieren (= dieser Lauf)

  MIN_EXPECTED: 3,             // Ausfall erst ab so vielen erwarteten Terminen
  DROP_RATIO: 0.5,             // Einbruch: weniger als 50 % der Erwartung …
  MIN_ABS_DROP: 5,             // … und mindestens 5 Termine weniger
  TOTAL_DROP_RATIO: 0.7,       // Gesamt: weniger als 70 % der Erwartung

  // Quellen, die nicht überwacht werden sollen (z. B. bewusst saisonale)
  IGNORE_SOURCE_IDS: [],
  // Muster für nicht überwachte Quellen. Manuelle Einträge („…_manuell“)
  // ziehen sich absichtlich zurück, sobald eine echte Quelle den Termin
  // liefert (z. B. Digi-Workshops → Stadt Münster) – das ist kein Ausfall.
  IGNORE_SOURCE_PATTERNS: [/_manuell$/],

  ALWAYS_REPORT: false,       // true = auch ohne Befund eine Mail (nur zum Testen!)
  NOTIFY_ON_CHECK_ERROR: false, // true = Mail, wenn GitHub nicht erreichbar ist

  USER_AGENT: 'coerde-kalender-gesundheitspruefung',
  SUBJECT_PREFIX: 'Coerde-Kalender',
};

// ---------------------------------------------------------------------------
// Hilfsfunktionen
// ---------------------------------------------------------------------------
function clean(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

function pick(obj, keys) {
  for (const k of keys) {
    const v = obj[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return '';
}

function todayIsoInZone(timeZone) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(new Date());
  const map = {};
  for (const p of parts) map[p.type] = p.value;
  return `${map.year}-${map.month}-${map.day}`;
}

function isoDate(v) {
  const m = clean(v).match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? `${m[1]}-${m[2]}-${m[3]}` : '';
}

function escapeHtml(s) {
  return clean(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function fmtDateTime(iso) {
  return new Intl.DateTimeFormat('de-DE', {
    timeZone: CONFIG.TIMEZONE,
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  }).format(new Date(iso));
}

// Zählt anstehende, veröffentlichbare Termine je Quelle.
function countUpcoming(events, todayIso) {
  const counts = {};
  for (const e of events) {
    if (!e) continue;
    const title = pick(e, ['Titel', 'title']);
    const start = isoDate(pick(e, ['date_start', 'start_date']));
    if (!title || !start) continue;
    const pub = clean(e.publish).toLowerCase();
    if (['nein', 'no', 'false', '0', 'n'].includes(pub)) continue;
    const end = isoDate(pick(e, ['date_end', 'end_date'])) || start;
    if (end < todayIso) continue;
    const sid = clean(pick(e, ['source_id'])) || '(ohne source_id)';
    counts[sid] = (counts[sid] || 0) + 1;
  }
  return counts;
}

async function httpGetJson(url) {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: {
      'User-Agent': CONFIG.USER_AGENT,
      Accept: 'application/vnd.github+json, application/json',
    },
    json: true,
  });
  return typeof resp === 'string' ? JSON.parse(resp) : resp;
}

function eventsFromPayload(payload) {
  if (Array.isArray(payload)) return payload;
  if (payload && Array.isArray(payload.events)) return payload.events;
  return [];
}

// ---------------------------------------------------------------------------
// 1) Aktueller Lauf
// ---------------------------------------------------------------------------
const todayIso = todayIsoInZone(CONFIG.TIMEZONE);
const currentEvents = $input.all().map((i) => i.json || {});
const nowCounts = countUpcoming(currentEvents, todayIso);

// ---------------------------------------------------------------------------
// 2) Frühere Stände von GitHub laden
// ---------------------------------------------------------------------------
let baselines = [];
let checkError = '';

try {
  const commitsUrl =
    `https://api.github.com/repos/${CONFIG.REPO}/commits` +
    `?path=${encodeURIComponent(CONFIG.FILE_PATH)}&sha=${CONFIG.BRANCH}&per_page=15`;
  const commits = await httpGetJson.call(this, commitsUrl);
  if (!Array.isArray(commits)) throw new Error('Commit-Liste hat ein unerwartetes Format');

  const cutoff = Date.now() - CONFIG.SKIP_RECENT_MINUTES * 60 * 1000;
  const older = commits
    .map((c) => ({
      sha: c.sha,
      date: (c.commit && c.commit.committer && c.commit.committer.date) || '',
    }))
    .filter((c) => c.sha && c.date && new Date(c.date).getTime() < cutoff)
    .slice(0, CONFIG.BASELINE_RUNS);

  for (const c of older) {
    try {
      const rawUrl = `https://raw.githubusercontent.com/${CONFIG.REPO}/${c.sha}/${CONFIG.FILE_PATH}`;
      const payload = await httpGetJson.call(this, rawUrl);
      baselines.push({ ...c, counts: countUpcoming(eventsFromPayload(payload), todayIso) });
    } catch (err) {
      console.log(`Quellen-Gesundheit: Stand ${c.sha.slice(0, 7)} nicht lesbar – ${err.message}`);
    }
  }
  if (!baselines.length) throw new Error('kein früherer Stand von events.json verfügbar');
} catch (err) {
  checkError = err.message || String(err);
}

if (checkError) {
  console.log(`Quellen-Gesundheit: Prüfung nicht möglich – ${checkError}`);
  if (!CONFIG.NOTIFY_ON_CHECK_ERROR) return [];
  const subject = `${CONFIG.SUBJECT_PREFIX}: Gesundheitsprüfung konnte nicht laufen`;
  const text = `Die Prüfung der Quellen konnte nicht durchgeführt werden.\n\nGrund: ${checkError}\n\nTermine in diesem Lauf: ${Object.values(nowCounts).reduce((a, b) => a + b, 0)}`;
  return [{ json: { alert: true, subject, text, html: `<p>${escapeHtml(text).replace(/\n/g, '<br>')}</p>`, problems: [], table: [] } }];
}

// ---------------------------------------------------------------------------
// 3) Vergleich
// ---------------------------------------------------------------------------
const ignoreIds = new Set(CONFIG.IGNORE_SOURCE_IDS);
const ignore = { has: (sid) => ignoreIds.has(sid) || CONFIG.IGNORE_SOURCE_PATTERNS.some((re) => re.test(sid)) };
const allSources = new Set(Object.keys(nowCounts));
for (const b of baselines) Object.keys(b.counts).forEach((s) => allSources.add(s));

const table = [];
const problems = [];

for (const sid of [...allSources].sort()) {
  const now = nowCounts[sid] || 0;
  const previous = baselines[0].counts[sid] || 0;
  const expected = Math.max(...baselines.map((b) => b.counts[sid] || 0));
  let status = 'ok';

  if (ignore.has(sid)) {
    status = 'ignoriert';
  } else if (expected >= CONFIG.MIN_EXPECTED && now === 0) {
    status = 'AUSFALL';
  } else if (expected - now >= CONFIG.MIN_ABS_DROP && now < expected * CONFIG.DROP_RATIO) {
    status = 'EINBRUCH';
  } else if (expected === 0 && now > 0) {
    status = 'neu';
  }

  const row = { source_id: sid, now, previous, expected, status };
  table.push(row);
  if (status === 'AUSFALL' || status === 'EINBRUCH') problems.push(row);
}

const totalNow = Object.entries(nowCounts)
  .filter(([s]) => !ignore.has(s))
  .reduce((a, [, n]) => a + n, 0);
const totalExpected = Math.max(
  ...baselines.map((b) =>
    Object.entries(b.counts)
      .filter(([s]) => !ignore.has(s))
      .reduce((a, [, n]) => a + n, 0)
  )
);
const totalAlert = totalExpected > 0 && totalNow < totalExpected * CONFIG.TOTAL_DROP_RATIO;

console.log(
  `Quellen-Gesundheit: ${totalNow} anstehende Termine (Erwartung ${totalExpected}), ` +
    `${problems.length} auffällige Quellen, verglichen mit ${baselines.length} früheren Ständen.`
);

if (!problems.length && !totalAlert && !CONFIG.ALWAYS_REPORT) {
  return [];
}

// ---------------------------------------------------------------------------
// 4) Mail aufbauen
// ---------------------------------------------------------------------------
const labels = {
  AUSFALL: 'liefert keine Termine mehr',
  EINBRUCH: 'liefert deutlich weniger Termine',
};

let subject;
const totalSuffix = totalAlert ? ` – Gesamtzahl stark gesunken (${totalNow} statt ${totalExpected})` : '';
if (problems.length === 1) {
  subject = `${CONFIG.SUBJECT_PREFIX}: ${problems[0].source_id} ${labels[problems[0].status]}${totalSuffix}`;
} else if (problems.length > 1) {
  subject = `${CONFIG.SUBJECT_PREFIX}: ${problems.length} Quellen auffällig${totalSuffix}`;
} else if (totalAlert) {
  subject = `${CONFIG.SUBJECT_PREFIX}: Terminzahl stark gesunken (${totalNow} statt ${totalExpected})`;
} else {
  subject = `${CONFIG.SUBJECT_PREFIX}: Gesundheitsprüfung ohne Befund`;
}

const baselineInfo = baselines.map((b) => `${fmtDateTime(b.date)} (${b.sha.slice(0, 7)})`).join(', ');
const order = { AUSFALL: 0, EINBRUCH: 1, neu: 2, ok: 3, ignoriert: 4 };
const sorted = [...table].sort((a, b) => order[a.status] - order[b.status] || b.expected - a.expected);

const textLines = [];
if (problems.length) {
  textLines.push('Auffällige Quellen:');
  for (const p of problems) {
    textLines.push(`- ${p.source_id}: ${labels[p.status]} – jetzt ${p.now}, erwartet ${p.expected} (letzter Lauf ${p.previous})`);
  }
  textLines.push('');
}
if (totalAlert) {
  textLines.push(`Gesamt: ${totalNow} anstehende Termine, erwartet ${totalExpected}.`, '');
}
textLines.push('Gezählt werden nur Termine, die heute noch anstehen – auch in den alten Ständen.');
textLines.push(`Vergleich mit: ${baselineInfo}`, '');
textLines.push('Alle Quellen (jetzt / letzter Lauf / erwartet / Status):');
for (const r of sorted) textLines.push(`- ${r.source_id}: ${r.now} / ${r.previous} / ${r.expected} / ${r.status}`);
textLines.push('', 'Nächste Schritte: in n8n die letzte Ausführung öffnen und bei der betroffenen Quelle prüfen,');
textLines.push('was Firecrawl bzw. der Abruf geliefert hat (leere Seite, geänderte Struktur, Fehlermeldung).');
const text = textLines.join('\n');

const color = { AUSFALL: '#b42318', EINBRUCH: '#b54708', neu: '#1a7f37', ok: '#475467', ignoriert: '#98a2b3' };
const rowsHtml = sorted
  .map(
    (r) =>
      `<tr><td style="padding:4px 10px">${escapeHtml(r.source_id)}</td>` +
      `<td style="padding:4px 10px;text-align:right">${r.now}</td>` +
      `<td style="padding:4px 10px;text-align:right">${r.previous}</td>` +
      `<td style="padding:4px 10px;text-align:right">${r.expected}</td>` +
      `<td style="padding:4px 10px;color:${color[r.status]};font-weight:${r.status === 'AUSFALL' || r.status === 'EINBRUCH' ? 700 : 400}">${r.status}</td></tr>`
  )
  .join('');

const problemsHtml = problems.length
  ? `<p><b>Auffällige Quellen:</b></p><ul>${problems
      .map((p) => `<li><b>${escapeHtml(p.source_id)}</b>: ${labels[p.status]} – jetzt ${p.now}, erwartet ${p.expected} (letzter Lauf ${p.previous})</li>`)
      .join('')}</ul>`
  : '';
const totalHtml = totalAlert ? `<p><b>Gesamt:</b> ${totalNow} anstehende Termine, erwartet ${totalExpected}.</p>` : '';

const html =
  `<div style="font-family:Arial,sans-serif;font-size:14px;color:#101828">` +
  problemsHtml +
  totalHtml +
  `<p style="color:#475467">Gezählt werden nur Termine, die heute noch anstehen – auch in den alten Ständen.<br>Vergleich mit: ${escapeHtml(baselineInfo)}</p>` +
  `<table style="border-collapse:collapse;font-size:13px"><thead><tr style="background:#f2f4f7">` +
  `<th style="padding:4px 10px;text-align:left">Quelle</th><th style="padding:4px 10px">jetzt</th>` +
  `<th style="padding:4px 10px">letzter Lauf</th><th style="padding:4px 10px">erwartet</th>` +
  `<th style="padding:4px 10px;text-align:left">Status</th></tr></thead><tbody>${rowsHtml}</tbody></table>` +
  `<p style="color:#475467">Nächste Schritte: in n8n die letzte Ausführung öffnen und bei der betroffenen Quelle prüfen, was Firecrawl bzw. der Abruf geliefert hat.</p>` +
  `</div>`;

return [
  {
    json: {
      alert: problems.length > 0 || totalAlert,
      subject,
      text,
      html,
      total_now: totalNow,
      total_expected: totalExpected,
      problems,
      table: sorted,
      compared_with: baselines.map((b) => ({ sha: b.sha, date: b.date })),
    },
  },
];
